import { imageCreditByKey } from '../content/imageCredits';

interface ResponsiveImageProps {
  /** Key from src/content/imageCredits.ts, e.g. 'hero-fortuner'. */
  name: string;
  /** Overrides the default credit alt text. */
  alt?: string;
  className?: string;
  sizes: string;
  /** Only the hero should opt out of lazy loading. */
  priority?: boolean;
  width?: number;
  height?: number;
}

/**
 * Renders a <picture> with WebP sources generated by scripts/fetch-images.mjs.
 * Widths come from the generated credit metadata, so the srcset always matches
 * the files actually on disk.
 */
export function ResponsiveImage({
  name,
  alt,
  className,
  sizes,
  priority = false,
  width,
  height,
}: ResponsiveImageProps) {
  const credit = imageCreditByKey[name];
  if (!credit) {
    throw new Error(`Unknown image "${name}". Run: node scripts/fetch-images.mjs`);
  }

  const srcSet = credit.widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', ');
  const largest = credit.widths[credit.widths.length - 1] ?? credit.naturalWidth;

  return (
    <picture>
      <source type="image/webp" srcSet={srcSet} sizes={sizes} />
      <img
        src={`/images/${name}-${largest}.webp`}
        alt={alt ?? credit.alt}
        className={className}
        width={width}
        height={height}
        sizes={sizes}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
      />
    </picture>
  );
}
